import React, { useState } from 'react';
import axios from 'axios';

const AiMatchmaker = ({ onLocationFound }) => {
  const [formData, setFormData] = useState({
    city: 'Meerut', 
    area: '', // NAYA FILED: Area ke liye
    rent: 6000,
    sharing_type: 2,
    has_ac: 0
  });

  const [recommendations, setRecommendations] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e) => {
    const value = (e.target.name === 'city' || e.target.name === 'area') ? e.target.value : Number(e.target.value);
    setFormData({ ...formData, [e.target.name]: value });
  };

  const findMatch = async () => {
    setLoading(true);
    setError('');
    
    try {
      // 1. FREE GEOCODING API CALL - Address ko Lat/Lng mein badalna
      const searchQuery = `${formData.area}, ${formData.city}`;
      const geoResponse = await axios.get(`https://nominatim.openstreetmap.org/search?format=json&q=${searchQuery}`);
      
      let userLat = 28.9845; // Default Meerut
      let userLng = 77.7064;
      
      if (geoResponse.data && geoResponse.data.length > 0) {
        userLat = parseFloat(geoResponse.data[0].lat);
        userLng = parseFloat(geoResponse.data[0].lon);
        // App.jsx ko batao ki map kahan le jana hai
        onLocationFound(userLat, userLng, formData.area || formData.city);
      } else {
        alert("Area exact map par nahi mila, city center dikha rahe hain.");
        onLocationFound(userLat, userLng, formData.city);
      }

      // 2. BACKEND API CALL (Ab hum user_lat aur user_lng bhej sakte hain)
      const payload = { ...formData, user_lat: userLat, user_lng: userLng };
      const response = await axios.post('http://localhost:8080/api/ai/recommend', payload);
      setRecommendations(response.data.recommendations);
      
    } catch (err) {
      setError('System connect nahi ho paya.');
    }
    setLoading(false);
  };

  return (
    <div style={{ background: "linear-gradient(135deg, #80608f 0%, #4a3b52 100%)", borderRadius: "16px", padding: "30px", color: "white", marginBottom: "40px" }}>
      <h2 style={{ margin: "0 0 20px 0", fontSize: "1.8rem" }}>✨ AI Matchmaker</h2>
      
      <div style={{ display: 'flex', gap: '15px', flexWrap: 'wrap', marginBottom: '20px' }}>
        
        {/* City */}
        <div style={{ flex: '1', minWidth: '150px' }}>
          <label>City</label>
          <select name="city" value={formData.city} onChange={handleChange} style={{ width: '100%', padding: '8px', marginTop: '5px', borderRadius: '4px' }}>
            <option value="Meerut">Meerut</option>
            <option value="Noida">Noida</option>
            <option value="Ghaziabad">Ghaziabad</option>
          </select>
        </div>

        {/* NAYA: Area / Landmark */}
        <div style={{ flex: '2', minWidth: '200px' }}>
          <label>Specific Area / College (e.g. Sector 62, MIET)</label>
          <input type="text" name="area" placeholder="Enter area..." value={formData.area} onChange={handleChange} style={{ width: '100%', padding: '8px', marginTop: '5px', borderRadius: '4px', border: 'none' }} />
        </div>

        {/* Max Rent */}
        <div style={{ flex: '1', minWidth: '150px' }}>
          <label>Max Rent (₹)</label>
          <input type="number" name="rent" value={formData.rent} onChange={handleChange} style={{ width: '100%', padding: '8px', marginTop: '5px', borderRadius: '4px', border: 'none' }} />
        </div>

        {/* Sharing */}
        <div style={{ flex: '1', minWidth: '100px' }}>
          <label>Sharing</label>
          <input type="number" name="sharing_type" value={formData.sharing_type} onChange={handleChange} style={{ width: '100%', padding: '8px', marginTop: '5px', borderRadius: '4px', border: 'none' }} />
        </div>
      </div>

      <button onClick={findMatch} disabled={loading} style={{ padding: "12px 24px", fontSize: "1.1rem", backgroundColor: "white", color: "#4a3b52", border: "none", borderRadius: "8px", fontWeight: "bold", cursor: "pointer", width: "100%" }}>
        {loading ? 'Searching & Mapping...' : 'Find My Match & Map Location'}
      </button>

      {error && <p style={{ color: '#ffb74d', marginTop: '15px' }}>{error}</p>}
    </div>
  );
};

export default AiMatchmaker;
